let page=1,items=[],total=0;const $=s=>document.querySelector(s),names={parcerias:'Parcerias',voluntariado:'Voluntariado',acolhimento:'Acolhimento',contato:'Contato'},states={novo:'Novo',em_contato:'Em contato',concluido:'Concluído',arquivado:'Arquivado'};
function el(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
async function api(url,opts){const r=await fetch(url,opts);const d=await r.json();if(!r.ok)throw Error(d.error||'Falha ao consultar.');return d;}
async function load(){ $('#feedback').textContent='';try{const q=new URLSearchParams(new FormData($('#filters')));q.set('pagina',page);const d=await api('/api/admin/entries?'+q);items=d.items;total=d.total;$('#entries').replaceChildren();for(const item of items){const details=el('details');details.className='entry';const summary=el('summary',item.nome+' · '+names[item.tipo]+' · '+states[item.situacao]);summary.append(el('small',new Date(item.criado_em).toLocaleString('pt-BR')));details.append(summary);details.append(el('p','Contato: '+item.contato),el('p','Organização ou interesse: '+(item.organizacao||'Não informado')),el('p','Mensagem: '+(item.mensagem||'Não informada')),el('small','Protocolo: '+item.id));const label=el('label','Situação');const select=el('select');for(const [v,t]of Object.entries(states)){const o=el('option',t);o.value=v;select.append(o);}select.value=item.situacao;label.append(select);const notesLabel=el('label','Anotações internas');const notes=el('textarea');notes.maxLength=2000;notes.value=item.notas;notesLabel.append(notes);const save=el('button','Salvar alterações');save.className='button';const result=el('p');result.className='result';result.setAttribute('role','status');save.onclick=async()=>{save.disabled=true;try{await api('/api/admin/update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:item.id,situacao:select.value,notas:notes.value})});result.textContent='Alterações salvas.';summary.firstChild.textContent=item.nome+' · '+names[item.tipo]+' · '+states[select.value];await stats();}catch(e){result.textContent=e.message;}finally{save.disabled=false;}};const remove=el('button','Excluir cadastro');remove.className='button light';remove.style.marginLeft='12px';remove.onclick=async()=>{if(!confirm('Excluir definitivamente este cadastro e suas anotações? Essa ação não pode ser desfeita.'))return;remove.disabled=true;try{await api('/api/admin/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:item.id,confirmacao:item.id})});await load();await stats();}catch(e){result.textContent=e.message;remove.disabled=false;}};details.append(label,notesLabel,save,remove,result);$('#entries').append(details);}if(!items.length)$('#entries').append(el('p','Nenhum cadastro encontrado para estes filtros.'));$('#count').textContent=total+' cadastro(s) encontrado(s)';$('#page').textContent='Página '+page;$('#prev').disabled=page===1;$('#next').disabled=page*50>=total;}catch(e){$('#feedback').textContent=e.message;$('#count').textContent='Consulta indisponível';}}
async function stats(){window.dispatchEvent(new Event('admin-data-updated'));}
window.addEventListener('admin-data-updated',()=>load());
$('#filters').onsubmit=e=>{e.preventDefault();page=1;load();};$('#prev').onclick=()=>{if(page>1){page--;load();}};$('#next').onclick=()=>{page++;load();};
$('#export').onclick=()=>{const cell=v=>'"'+String(/^[=+\-@\t\r]/.test(String(v))?"'"+v:v??'').replaceAll('"','""')+'"';const cols=['id','tipo','nome','contato','organizacao','mensagem','situacao','notas','criado_em'];const csv='\uFEFF'+[cols,...items.map(i=>cols.map(k=>i[k]))].map(row=>row.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=el('a');a.href=url;a.download='cadastros-mais-amor-pagina-'+page+'.csv';a.click();URL.revokeObjectURL(url);};load();stats();
